const NAV=[['workspace','cube','实训工作台','01'],['courses','book','教学与课程','02'],['competition','cup','竞赛中心','03'],['validation','flask','技术验证','04'],['records','database','数据与回放','05'],['integration','shield','接入与安全','06']];
const LABS=[
 {id:1,name:'机器人基础与安全',level:'L0',scene:'coffee',type:'基础认知',desc:'认识本体、空间边界与状态机，验证暂停、急停和复位流程。',goal:'能区分软件仿真急停与实体硬件急停，理解任务中止和恢复的区别。',steps:['打开碰撞边界，检查机器人与固定设施的距离','运行咖啡任务并暂停，再恢复执行','触发软件急停，检查 ABORTED 事件与成绩','安全复位后重新运行，提交两次记录的差异'],output:'暂停、急停和复位的事件记录及风险说明。'},
 {id:2,name:'三维场景与语义建模',level:'L0',scene:'coffee',type:'空间智能',desc:'理解坐标系、对象 ID 与空间关系，构建任务可理解的语义环境。',goal:'理解场景对象、目标点和障碍物如何影响规划。',steps:['在三维与俯视视角中观察示例场地','点击咖啡台、桌位和机器人读取语义与坐标','打开语义图，识别物体与目标位置关系','切换目标点并导出任务包，对比坐标定义'],output:'对象关系说明及可复现任务 JSON。'},
 {id:3,name:'任务数据采集与回放',level:'L1',scene:'logistics',type:'数据工程',desc:'记录机器人位姿与执行事件，把一次行动转化为可复查的数据。',goal:'掌握带相对时间戳的轨迹与事件结构。',steps:['完成一次物流搬运任务','在数据与回放中查看轨迹和技能事件','逐帧拖动回放时间轴，定位抓取与放置时刻','导出 JSON 和 CSV，解释字段与数据来源'],output:'仿真轨迹数据包及字段说明。当前不采集真实 RGB-D、音视频或关节传感器数据。'},
 {id:4,name:'空间指代与目标定位',level:'L1',scene:'coffee',type:'空间智能',desc:'把语言中的服务对象解析为明确的空间交付点，处理缺失信息。',goal:'理解指令校验、目标消歧与空间定位之间的关系。',steps:['输入“给张老师送咖啡”，观察缺失交付点的提示','改为“把咖啡送到沙发交付点”并生成任务','切换 01 号桌和 02 号桌，对比末端位置','记录支持的句式和未支持的表达'],output:'规则解析成功与失败用例表；无需假设接入大模型。'},
 {id:5,name:'抓取与放置流程',level:'L1',scene:'logistics',type:'操作技能',desc:'串联接近、抓取、搬运和入柜，识别动作执行的前置条件。',goal:'掌握技能依赖关系，明确预设动画与接触物理之间的边界。',steps:['查看物流任务执行链','在编排器中将放置前移，观察校验结果','恢复正确顺序，分别选择 B-01 与 B-02 运行','对比两个目标的放置高度并整理实机验证清单'],output:'合法任务计划、执行记录和需要实测的夹持与负载条件。'},
 {id:6,name:'语音任务编排',level:'L2',scene:'coffee',type:'任务规划',desc:'从文本或浏览器语音输入，生成可检查的技能链，再进入执行。',goal:'理解语音转写、意图抽取和受控执行的分工。',steps:['使用文本输入生成一条递送任务','查看识别出的物体、交付位置与技能列表','加入返回起始位技能，运行完整任务','若浏览器支持语音识别，可在授权后对照转写结果'],output:'结构化任务定义与解析测试记录。浏览器语音服务不等同于本地 ASR。'},
 {id:7,name:'规划基线与虚实对照',level:'L3',scene:'logistics',type:'科研验证',desc:'固定随机种子，对照规划方法；导入实测轨迹后计算位置误差。',goal:'掌握可复现的对照实验和时间对齐后的 XZ 位置误差。',steps:['进入技术验证，设置种子与障碍物数量','在同一组环境中运行 A* 与直线路径基线','检查通过率、成功样本路径长度和逐次结果','具备实测轨迹时导入 JSON，核对坐标与相对时间基准'],output:'批量验证 CSV；有实测数据时另附轨迹 RMSE 报告。'},
 {id:8,name:'综合任务竞赛',level:'L4',scene:'coffee',type:'综合应用',desc:'围绕冻结赛题完成任务，通过规则评分与裁判复核闭环评价。',goal:'理解可复现赛题、公平对照和过程证据的重要性。',steps:['切换教师或裁判体验身份，配置并冻结赛题','以学生身份输入参赛显示名并启动挑战','查看本地榜单、评分分项和任务回放','填写实验结论与改进建议后提交'],output:'带规则快照的竞赛记录、成绩与实验报告。非官方赛制。'}
];
const KEY='fieldlab-v01';let storeOK=true,db;try{db=JSON.parse(localStorage.getItem(KEY)||'null');}catch{db=null;storeOK=false;}db={role:'student',name:'体验学生',records:[],assignments:[],reports:[],contest:null,...(db||{})};
function save(){try{localStorage.setItem(KEY,JSON.stringify(db));storeOK=true;}catch{storeOK=false;toast('浏览器存储不可用或已满，请立即导出重要记录。');}}
let page='workspace',sceneKey='coffee',target='table1',seed=42,count=1,speed=.65,algorithm='astar',skills=defaultSkills('coffee'),activeLab=null,activeContest=null,sim,scene,recordSaved=false,eventSeen=0,planDraft=[],batchResults=null,batchConfig=null,comparison=null,realTrace=null,replay=null,replayTimer=null,courseFilter='all';
const statusNames={READY:'就绪',RUNNING:'运行中',PAUSED:'已暂停',SUCCEEDED:'已完成',FAILED:'已停止',ABORTED:'已急停'};
const date=s=>new Date(s).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
const seconds=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function download(name,data,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),5000);}
function csv(rows){if(!rows.length)return '';const keys=Object.keys(rows[0]);const field=v=>{let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};return '\uFEFF'+[keys.map(field).join(','),...rows.map(r=>keys.map(k=>field(r[k])).join(','))].join('\r\n');}
function heading(eyebrow,title,desc,actions=''){return `<section class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}<span class="heading-dot">.</span></h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></section>`;}
function stat(label,value,note,accent=false){return `<div class="stat-card panel ${accent?'accent':''}"><span>${label}</span><strong>${value}</strong><p>${note}</p></div>`;}
function empty(title,desc,action='',symbol='database'){return `<div class="empty-state"><div class="empty-symbol">${icon(symbol)}</div><h3>${title}</h3><p>${desc}</p>${action}</div>`;}
function openModal(title,subtitle,body){$('#modalContent').innerHTML=`<div class="modal-heading"><div><h2>${title}</h2><p>${subtitle||''}</p></div><button class="icon-btn" data-action="close" aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal();icons($('#modal'));}
function closeModal(){clearInterval(replayTimer);replayTimer=null;$('#modal').close();}
function canConfigure(){return ['teacher','judge','admin'].includes(db.role);}
function guardRunning(){if(['RUNNING','PAUSED'].includes(sim?.status)){toast('请完成或中止当前任务，再变更实验配置。');return true;}return false;}
function config(){return {scene:sceneKey,target,seed,count,speed,algorithm,skills:[...skills]};}
function rebuild(){sim=new Simulation(config());recordSaved=false;eventSeen=-1;scene?.setEnvironment(sim.env,target);$('#estopOverlay').hidden=true;$('#targetSelect').innerHTML=Object.entries(SCENARIOS[sceneKey].targets).map(([id,t])=>`<option value="${id}" ${id===target?'selected':''}>${t.name}</option>`).join('');$('#speedSelect').value=String(speed);$('#sceneId').textContent=`SCENE / ${SCENARIOS[sceneKey].code}-01`;$('#taskTemplateLabel').textContent=sceneKey==='coffee'?'COF · 常温模拟杯递送':'LOG · 轻量训练箱入柜';$$('[data-scene]').forEach(b=>b.classList.toggle('active',b.dataset.scene===sceneKey));$('#commandInput').value=sceneKey==='coffee'?`把咖啡送到${SCENARIOS[sceneKey].targets[target].name}`:`把箱子送到 ${SCENARIOS[sceneKey].targets[target].name}`;renderSkills();updateUI();}
function changeScene(key){if(guardRunning())return;activeContest=null;stopReplay();sceneKey=key;target=Object.keys(SCENARIOS[key].targets)[0];skills=defaultSkills(key);rebuild();renderIntent();}
function renderSkills(){const s=replay?{completed:replay.completed||0,index:replay.stepIndex??-1,status:'REPLAY'}:sim;$('#skillCount').textContent=`${skills.length} 个技能`;$('#skillList').innerHTML=skills.map((k,i)=>`<li class="${i<s.completed?'done':i===s.index?'running':''}"><span class="step-number">${i<s.completed?'✓':String(i+1).padStart(2,'0')}</span><span class="step-text"><strong>${SKILLS[k].name}</strong><span>${SKILLS[k].desc}</span></span>${i===s.index&&s.status==='RUNNING'?'<span class="step-state">执行中</span>':''}</li>`).join('');}
function updateUI(){if(!sim)return;const running=['RUNNING','PAUSED'].includes(sim.status);$('#liveStatus').innerHTML=`<i class="status-dot" style="background:${sim.status==='ABORTED'?'#d37861':'#789972'}"></i>${replay?'轨迹回放':statusNames[sim.status]}`;$('#liveTime').textContent=seconds(replay?.time||sim.elapsed);$('#liveDistance').textContent=(replay?.distance??sim.distance).toFixed(2);const position=replay?.pose||sim.pos;$('#livePos').textContent=`${position.x.toFixed(2)} / ${position.z.toFixed(2)}`;$('#targetSelect').disabled=running||!!activeContest||!!replay;$('#speedSelect').disabled=running||!!activeContest||!!replay;$('#progressText').textContent=activeContest?`竞赛 · ${statusNames[sim.status]}`:replay?'正在复盘历史记录':statusNames[sim.status];const done=replay?.completed??sim.completed;$('#progressNum').textContent=`${done} / ${skills.length}`;$('#progressBar').style.width=`${done/skills.length*100}%`;if(replay)renderSkills();$('#runButton').innerHTML=icon(sim.status==='RUNNING'?'pause':'play')+(replay?'结束回放':sim.status==='RUNNING'?'暂停仿真':sim.status==='PAUSED'?'继续执行':sim.status==='READY'?'开始仿真':'再次运行');$('#runButton').disabled=sim.status==='ABORTED'&&!replay;$('#estopOverlay').hidden=sim.status!=='ABORTED';if(eventSeen!==sim.events.length){eventSeen=sim.events.length;renderSkills();scene?.drawPath(sim.path);$('#eventCount').textContent=`${sim.events.length} 条事件 · 相对时间戳`;$('#eventStream').innerHTML=sim.events.length?sim.events.slice(-6).map(e=>`<span class="event-chip ${['NO_PATH','ESTOP','COLLISION'].includes(e.type)?'error':''}"><time>${seconds(e.t)}</time>${esc(e.message)}</span>`).join(''):'<span class="muted small">准备就绪。配置任务后点击「开始仿真」。</span>';}}
function finish(){if(recordSaved||!['SUCCEEDED','FAILED','ABORTED'].includes(sim.status))return;recordSaved=true;const rules=activeContest?.rules;const r=sim.record({student:db.name,labId:activeLab,contestId:activeContest?.id||null,contestName:activeContest?.name||null,rules:rules||{completion:50,safety:30,efficiency:20,timeLimit:90},review:null});db.records.unshift(r);db.records=db.records.slice(0,50);save();toast(sim.status==='SUCCEEDED'?`任务完成，仿真得分 ${r.score.total}，已保存运行证据。`:'本次中止记录已归档，可在「数据与回放」中复盘。');if(page==='records')renderRecords();if(page==='competition')renderCompetition();}
function startRun(){if(replay){stopReplay();rebuild();return;}if(sim.status==='RUNNING'){sim.pause();updateUI();return;}if(sim.status==='PAUSED'){sim.resume();updateUI();return;}if(sim.status==='ABORTED'){toast('请先执行安全复位。');return;}if(sim.status!=='READY')rebuild();try{sim.start();scene?.drawPath(sim.path);updateUI();finish();}catch(e){toast(e.message);}}
function renderIntent(result){const info=result||{intent:sceneKey==='coffee'?'递送咖啡':'搬箱入柜',target};$('#intentResult').className='intent-result';$('#intentResult').innerHTML=`<span>意图 <b>${esc(info.intent)}</b></span><span>对象 <b>${sceneKey==='coffee'?'常温模拟杯':'轻量训练箱'}</b></span><span>目标 <b>${SCENARIOS[sceneKey].targets[info.target].name}</b></span><span class="valid-label">✓ 待执行</span>`;}
function parse(){const r=parseCommand($('#commandInput').value,sceneKey);if(r.action==='estop'){estop();return;}if(r.action==='pause'){sim.pause();updateUI();return;}if(guardRunning())return;if(activeContest){toast('竞赛任务已冻结，请按赛题配置运行。');return;}if(r.error){$('#intentResult').className='intent-result error';$('#intentResult').textContent=r.error;return;}const cmd=$('#commandInput').value;target=r.target;skills=r.skills;rebuild();$('#commandInput').value=cmd;renderIntent(r);toast('任务已校验，点击「开始仿真」执行。');}
function estop(){if(replay){stopReplay();rebuild();return;}if(sim.abort()){finish();updateUI();}}
function navigate(id){page=NAV.some(n=>n[0]===id)?id:'workspace';$('#workspacePage').hidden=page!=='workspace';$('#dynamicPage').hidden=page==='workspace';$('#breadcrumb').textContent=NAV.find(n=>n[0]===page)[2];$$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.page===page));$('#sidebar').classList.remove('open');if(page==='courses')renderCourses();if(page==='competition')renderCompetition();if(page==='validation')renderValidation();if(page==='records')renderRecords();if(page==='integration')renderIntegration();if(page==='workspace'){scene?.resize();updateUI();}history.replaceState(null,'','#'+page);window.scrollTo({top:0,behavior:'instant'});}
function renderCourses(){const finished=new Set(db.reports.map(r=>r.labId));$('#dynamicPage').innerHTML=heading('TEACHING / 02','教学与课程','围绕真实任务组织学习，让每次实验都留下可复查的过程。',canConfigure()?`<button class="btn dark" data-action="assignment">${icon('plus')}发布教学任务</button>`:'')+`<div class="stat-grid">${stat('实验单元','08','覆盖安全、空间、规划与竞赛',true)}${stat('已提交实验报告',finished.size.toString(),'按本浏览器提交记录统计')}${stat('当前教学任务',db.assignments.length.toString(),'保存在当前浏览器')}${stat('已记录实验',db.records.length.toString(),'任务与轨迹证据可导出')}</div><div class="filter-row">${[['all','全部实验'],['base','基础 · L0–L1'],['advanced','进阶 · L2–L4']].map(([id,t])=>`<button class="filter-pill ${courseFilter===id?'active':''}" data-course-filter="${id}">${t}</button>`).join('')}<span class="small muted" style="margin-left:auto">PRD §8.1 · 八个教学单元</span></div><div class="course-grid">${LABS.filter(l=>courseFilter==='all'||(courseFilter==='base'?Number(l.level[1])<=1:Number(l.level[1])>=2)).map(l=>`<article class="course-card panel"><div class="course-top"><span class="course-number">${String(l.id).padStart(2,'0')}</span><span class="tag ${finished.has(l.id)?'coral':''}">${finished.has(l.id)?'已提交报告':l.level+' · '+l.type}</span></div><h3>${l.name}</h3><p>${l.desc}</p><div class="course-bottom"><span>${SCENARIOS[l.scene].name}场景</span><button data-lab="${l.id}">进入实验 ${icon('arrow')}</button></div></article>`).join('')}</div><div class="section-head"><div><h2>教学任务与实验报告</h2><p>当前浏览器内的教学演示记录；可导出后归档。</p></div><button class="btn" data-action="submit-report">${icon('file')}提交实验报告</button></div><div class="panel">${db.assignments.length?db.assignments.map(a=>`<div class="assignment-row"><span class="tag">实验 ${String(a.labId).padStart(2,'0')}</span><div><strong>${esc(a.title)}</strong><p>${esc(a.note)} · ${a.due?'截止 '+esc(a.due):'未设截止日期'}</p></div><button class="btn" data-lab="${a.labId}">查看实验</button></div>`).join(''):empty('从一个实验开始','选择上方课程，按照实验步骤完成任务，再提交自己的观察、证据与结论。','','book')}</div>${db.reports.length?`<div class="section-head"><h2>已提交报告</h2></div><div class="panel table-wrap"><table><thead><tr><th>实验</th><th>提交者</th><th>提交时间</th><th>证据记录</th><th>操作</th></tr></thead><tbody>${db.reports.map(r=>`<tr><td>${LABS.find(l=>l.id===r.labId)?.name||'综合实验'}</td><td>${esc(r.student)}</td><td>${date(r.createdAt)}</td><td>${esc(r.runId.slice(0,8))}</td><td><button class="text-btn" data-report="${r.id}">查看报告</button></td></tr>`).join('')}</tbody></table></div>`:''}`;}
function labModal(id){const l=LABS.find(x=>x.id===Number(id));openModal(`实验 ${String(l.id).padStart(2,'0')} · ${l.name}`,`${l.level} / ${l.type} / ${SCENARIOS[l.scene].name}`,`<div class="notice">${l.goal}</div><h3>实验步骤</h3><ol>${l.steps.map(s=>`<li>${s}</li>`).join('')}</ol><h3>提交成果</h3><p>${l.output}</p><div class="modal-actions"><button class="btn" data-action="close">稍后学习</button><button class="btn primary" data-load-lab="${l.id}">${icon('play')}加载实验</button></div>`);}
function renderCompetition(){const c=db.contest;const entries=c?db.records.filter(r=>r.contestId===c.id).sort((a,b)=>(b.review?.score??b.score.total)-(a.review?.score??a.score.total)||a.duration-b.duration):[];$('#dynamicPage').innerHTML=heading('CHALLENGE / 03','竞赛中心','固定初始条件，用完整的过程证据支撑每一份成绩。',`<button class="btn" data-action="export-leaderboard">${icon('download')}导出成绩</button>`)+(c?`<div class="frozen-banner"><div><span class="tag">赛题已冻结 · 校内自定义规则</span><h3 style="margin-top:10px">${esc(c.name)}</h3><p>${SCENARIOS[c.scene].name} / ${SCENARIOS[c.scene].targets[c.target].name} / 种子 ${c.seed} / ${c.count} 个可变障碍 · 规则保存于 ${date(c.createdAt)}</p></div><button class="btn primary" data-action="challenge">${icon('play')}开始挑战</button></div>`:`<div class="intro-strip"><div><strong>让比赛从同一个起点开始</strong><p>冻结任务、随机种子与计分权重后，每次挑战均保存规则快照。当前为浏览器内的竞赛流程原型，成绩来自运动学仿真。</p></div><span class="tag">暂无冻结赛题</span></div>`)+`<div class="two-columns"><section class="panel form-panel"><h2>${c?'冻结规则快照':'配置一场新比赛'}</h2><p>${canConfigure()?'教师、裁判可配置本地赛题，冻结后才开放挑战。':'切换顶部「体验身份」为教师或裁判，可体验赛题配置。'}</p><div class="form-grid"><label class="wide">赛题名称<input id="contestName" value="${esc(c?.name||'咖啡递送综合挑战')}" ${c?'disabled':''}></label><label>任务场景<select id="contestScene" ${c?'disabled':''}>${Object.entries(SCENARIOS).map(([k,s])=>`<option value="${k}" ${c?.scene===k?'selected':''}>${s.name}</option>`).join('')}</select></label><label>交付目标<select id="contestTarget" ${c?'disabled':''}>${Object.entries(SCENARIOS[c?.scene||'coffee'].targets).map(([k,s])=>`<option value="${k}" ${c?.target===k?'selected':''}>${s.name}</option>`).join('')}</select></label><label>随机种子<input id="contestSeed" type="number" min="0" max="999999" value="${c?.seed??42}" ${c?'disabled':''}></label><label>可变障碍数量<select id="contestCount" ${c?'disabled':''}>${[0,1,2,3,4].map(v=>`<option ${v===(c?.count??1)?'selected':''}>${v}</option>`).join('')}</select></label><label>完成度权重<input id="weightCompletion" type="number" min="0" max="100" value="${c?.rules.completion??50}" ${c?'disabled':''}></label><label>安全检查权重<input id="weightSafety" type="number" min="0" max="100" value="${c?.rules.safety??30}" ${c?'disabled':''}></label><label>效率权重<input id="weightEfficiency" type="number" min="0" max="100" value="${c?.rules.efficiency??20}" ${c?'disabled':''}></label><label>运行时限 s<input id="contestTime" type="number" min="20" max="600" value="${c?.rules.timeLimit??90}" ${c?'disabled':''}></label></div><div class="form-footer"><span class="small muted">权重合计须为 100 · 仿真速度 0.65 m/s</span><button class="btn ${c?'':'dark'}" data-action="${c?'new-contest':'freeze-contest'}" ${!canConfigure()?'disabled':''}>${icon(c?'plus':'shield')}${c?'建立新赛题':'校验并冻结'}</button></div></section><section class="panel form-panel"><h2>成绩由证据产生</h2><p>以下计算规则随赛题保存，便于选手与裁判复核。</p><div class="help-item"><h3>01 / 完成度</h3><p>完成度权重 × 已完成技能数 ÷ 总技能数。</p></div><div class="help-item" style="margin-top:12px"><h3>02 / 安全检查</h3><p>运行未触发碰撞检查时获得该项分值。软件急停使整次成绩为 0；此项不代表实体机器人安全认证。</p></div><div class="help-item" style="margin-top:12px"><h3>03 / 效率</h3><p>仅成功任务计分：效率权重 × max(0, 1 − 运行时间 ÷ 时限)。超时自动停止并记录。</p></div><div class="notice coral">裁判可补充复核分数与理由，原始自动评分保留。当前身份切换用于流程体验，未实现正式账号权限。</div><label>参赛显示名<input id="studentName" maxlength="30" value="${esc(db.name)}"></label><div class="form-footer"><button class="btn" data-action="save-name">保存显示名</button>${c?'<button class="btn primary" data-action="challenge">进入本轮挑战 →</button>':''}</div></section></div><div class="section-head"><div><h2>本轮榜单</h2><p>${entries.length} 次本地参赛记录 · 按最终分数排序，同分按耗时排序</p></div>${c?'<span class="tag">同一任务 · 同一种子 · 同一规则</span>':''}</div><section class="panel">${entries.length?`<div class="table-wrap"><table><thead><tr><th>排名</th><th>选手</th><th>完成情况</th><th>运行时间</th><th>自动分</th><th>最终分</th><th>操作</th></tr></thead><tbody>${entries.map((r,i)=>`<tr><td><b class="mono">${String(i+1).padStart(2,'0')}</b></td><td>${esc(r.student)}<small>${date(r.createdAt)}</small></td><td>${r.completed}/${r.skills.length} 技能 <span class="status-chip ${r.status==='SUCCEEDED'?'':'failed'}">${statusNames[r.status]}</span></td><td>${r.duration}s</td><td>${r.score.total}</td><td><b>${r.review?.score??r.score.total}</b>${r.review?'<small>已人工复核</small>':''}</td><td><div class="cell-actions"><button class="text-btn" data-record="${r.id}">回放</button>${canConfigure()?`<button class="text-btn" data-review="${r.id}">复核</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('等待第一份参赛记录',c?'点击「开始挑战」，使用冻结的赛题运行任务，结果将自动加入本轮榜单。':'先配置并冻结赛题，再邀请体验者开始挑战。','','cup')}</section>`;}
function renderValidation(){const last=db.records.find(r=>r.status==='SUCCEEDED');$('#dynamicPage').innerHTML=heading('RESEARCH / 04','技术验证','以可复现的实验，比较方法、定位差异、积累证据。',`<button class="btn" data-action="export-batch">${icon('download')}导出实验数据</button>`)+`<div class="intro-strip"><div><strong>同一组环境，两种规划方法</strong><p>固定随机种子与任务目标，对 A* 网格规划和直线路径基线逐次执行碰撞检查。结果由本地计算产生，不代表物理抓取、动力学或实机成功率。</p></div><span class="tag">确定性实验</span></div><div class="two-columns"><section class="panel form-panel"><h2>路径规划对照实验</h2><p>采用 0.25 m 网格及 0.28 m 机器人平面安全半径，均为原型设定值。</p><div class="form-grid"><label>任务场景<select id="batchScene">${Object.entries(SCENARIOS).map(([k,s])=>`<option value="${k}" ${k===(batchConfig?.scene||'coffee')?'selected':''}>${s.name}</option>`).join('')}</select></label><label>目标位置<select id="batchTarget">${Object.entries(SCENARIOS[batchConfig?.scene||'coffee'].targets).map(([k,s])=>`<option value="${k}" ${k===(batchConfig?.target||'table1')?'selected':''}>${s.name}</option>`).join('')}</select></label><label>起始随机种子<input id="batchSeed" type="number" min="0" max="999999" value="${batchConfig?.seed??42}"></label><label>实验环境数<select id="batchEpisodes">${[10,20,50].map(v=>`<option ${v===(batchConfig?.episodes??20)?'selected':''}>${v}</option>`).join('')}</select></label><label>可变障碍数量<select id="batchCount">${[0,1,2,3,4].map(v=>`<option ${v===(batchConfig?.count??2)?'selected':''}>${v}</option>`).join('')}</select></label><label>版本标识<input value="${VERSION} / kinematic" disabled></label></div><div class="form-footer"><span class="small muted">一次实验同时计算两种方法</span><button class="btn dark" data-action="run-batch" id="batchButton">${icon('play')}运行对照实验</button></div></section><section class="panel form-panel" id="batchOutput">${batchResults?batchHTML():empty('实验结果将在这里生成','相同种子生成相同的障碍布局。比较路径通过率，并检查每一个失败样本。','','chart')}</section></div><div class="section-head"><div><h2>虚实轨迹对照</h2><p>将实测 XZ 位置轨迹按相对时间对齐，计算重叠区间的位置误差。</p></div><button class="text-btn" data-action="telemetry-format">查看数据格式 ↗</button></div><div class="two-columns"><section class="panel form-panel"><h2>选择仿真基线并导入实测数据</h2><p>上传者需核对同一任务、米制单位、坐标原点和起始时间；文件仅在当前浏览器计算。</p><label>仿真基线记录<select id="compareBaseline">${db.records.filter(r=>r.trace.length>1).map(r=>`<option value="${r.id}">${date(r.createdAt)} · ${SCENARIOS[r.scene].name} · ${r.duration}s</option>`).join('')||'<option value="">请先完成一次仿真</option>'}</select></label><label class="check-label" style="margin:18px 0"><input type="checkbox" id="coordinateConfirmed">已核对同一任务、米制坐标与相对时间（t 从任务开始计时）</label><button class="btn" data-action="import-telemetry">${icon('upload')}导入实测轨迹 JSON / JSONL</button><div class="notice">实测来源标注为「用户提供，未经设备认证」。平台不会自动把示例或仿真数据当作实测数据。</div></section><section class="panel form-panel" id="comparisonOutput">${comparison?comparisonHTML():empty('等待实测轨迹','尚无实测数据时，不展示虚构的虚实误差。你仍可运行上方的规划对照实验。','','link')}</section></div>${batchResults?`<div class="section-head"><h2>逐次实验明细</h2><span class="small muted">完整结果可导出 CSV</span></div><div class="panel table-wrap"><table><thead><tr><th>随机种子</th><th>规划方法</th><th>路径检查结果</th><th>两段总路径长度</th></tr></thead><tbody>${batchResults.map(r=>`<tr><td class="mono">${r.seed}</td><td>${r.algorithm==='astar'?'A* 网格规划':'直线路径基线'}</td><td><span class="status-chip ${r.success?'':'failed'}">${r.success?'通过':'未找到可行路径'}</span></td><td>${r.distance===null?'—':r.distance+' m'}</td></tr>`).join('')}</tbody></table></div>`:''}`;}
function batchHTML(){const data=['astar','direct'].map(a=>{const list=batchResults.filter(r=>r.algorithm===a),ok=list.filter(r=>r.success);return {algorithm:a,count:list.length,ok:ok.length,pct:ok.length/list.length*100,mean:ok.length?ok.reduce((n,r)=>n+r.distance,0)/ok.length:null};});return `<h2>路径可行性对照</h2><p>${batchConfig.episodes} 个环境 × 2 种方法 · 种子 ${batchConfig.seed}–${Number(batchConfig.seed)+batchConfig.episodes-1}</p><div class="bar-chart">${data.map((a,i)=>`<div class="chart-row"><span>${i?'直线路径':'A* 网格规划'}</span><div class="chart-track"><div class="chart-bar ${i?'coral':''}" style="width:${a.pct}%"></div></div><strong>${a.pct.toFixed(0)}<small style="font-size:10px">%</small></strong></div>`).join('')}</div><div class="result-metrics">${data.map((a,i)=>`<div><span>${i?'直线路径':'A*'} · 成功样本均长</span><b>${a.mean?.toFixed(2)||'—'} <small>m</small></b><span>${a.ok}/${a.count} 个环境通过</span></div>`).join('')}</div><div class="notice">长度均值只统计各方法成功样本，样本集合不同。成功率表示两段路径均通过静态平面碰撞检查。</div>`;}
function trajectorySVG(trace,other=null,marker=null){const px=x=>(x+5)*50,pz=z=>(z+3.5)*50;const poly=arr=>arr.map(p=>`${px(p.x).toFixed(1)},${pz(p.z).toFixed(1)}`).join(' ');return `<svg class="chart-svg" viewBox="0 0 500 350" role="img" aria-label="XZ 平面轨迹图"><defs><pattern id="mapGrid" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" fill="none" stroke="#dce3d2" stroke-width=".6"/></pattern></defs><rect width="500" height="350" fill="url(#mapGrid)"/><text x="12" y="23" fill="#82956f" font-size="10">XZ 平面 / 单位 m</text><polyline points="${poly(trace)}" fill="none" stroke="#6e9165" stroke-width="2.5" stroke-linejoin="round"/>${other?`<polyline points="${poly(other)}" fill="none" stroke="#df8c72" stroke-width="2" stroke-dasharray="5 3"/>`:''}${trace.length?`<circle cx="${px(trace[0].x)}" cy="${pz(trace[0].z)}" r="5" fill="#506d48"/><circle cx="${px(trace.at(-1).x)}" cy="${pz(trace.at(-1).z)}" r="5" fill="#df8c72"/>`:''}${marker?`<circle cx="${px(marker.x)}" cy="${pz(marker.z)}" r="9" fill="#e07563" stroke="#fff8eb" stroke-width="3"/>`:''}</svg>`;}
function comparisonHTML(){return `<h2>已计算轨迹位置误差</h2><p>${esc(comparison.filename)} · 用户提供，未经设备认证</p>${trajectorySVG(comparison.baseline.trace,realTrace)}<div class="chart-legend"><span><i></i>仿真轨迹</span><span><i class="coral"></i>导入轨迹</span></div><div class="result-metrics"><div><span>XZ 位置 RMSE</span><b>${comparison.rmse.toFixed(4)} <small>m</small></b></div><div><span>最大位置误差</span><b>${comparison.max.toFixed(4)} <small>m</small></b></div><div><span>重叠样本</span><b>${comparison.samples.length}</b></div></div><p class="page-note">仿真轨迹按时间线性插值；重叠区间 ${comparison.overlap.map(v=>v.toFixed(2)).join('–')} s。此结果只反映提供的两组 XZ 数据。</p><button class="btn" data-action="export-comparison">${icon('download')}导出对照报告</button>`;}
function renderRecords(filter='all',search=''){const rs=db.records.filter(r=>(filter==='all'||r.status===filter)&&(`${r.student} ${r.id} ${SCENARIOS[r.scene].name}`).includes(search));const total=db.records.reduce((a,r)=>a+r.trace.length,0);$('#dynamicPage').innerHTML=heading('EVIDENCE / 05','数据与回放','把任务、参数、轨迹与事件放在同一份记录中。',`<button class="btn" data-action="export-all">${icon('download')}导出全部记录</button>`)+`<div class="stat-grid">${stat('运行记录',db.records.length.toString(),'最多保留最近 50 次',true)}${stat('成功任务',db.records.filter(r=>r.status==='SUCCEEDED').length.toString(),'按任务状态核验')}${stat('轨迹采样点',total.toLocaleString(),'约 0.15 s 采样间隔')}${stat('实机连接','00','尚未接入机器人设备')}</div><div class="filter-row"><button class="filter-pill ${filter==='all'?'active':''}" data-record-filter="all">全部记录</button><button class="filter-pill ${filter==='SUCCEEDED'?'active':''}" data-record-filter="SUCCEEDED">已完成</button><button class="filter-pill ${filter==='ABORTED'?'active':''}" data-record-filter="ABORTED">已急停</button><button class="filter-pill ${filter==='FAILED'?'active':''}" data-record-filter="FAILED">已停止</button><input class="search-input" id="recordSearch" placeholder="搜索姓名、场景或记录 ID" value="${esc(search)}" aria-label="搜索记录"></div><section class="panel">${rs.length?`<div class="table-wrap"><table><thead><tr><th>任务 / 时间</th><th>操作者</th><th>状态</th><th>时长 / 里程</th><th>评分</th><th>数据来源</th><th>证据</th></tr></thead><tbody>${rs.map(r=>`<tr><td><strong>${SCENARIOS[r.scene].name}</strong><small>${date(r.createdAt)} · ${esc(r.id.slice(0,8))}</small></td><td>${esc(r.student)}<small>${r.labId?'实验 '+String(r.labId).padStart(2,'0'):r.contestId?'竞赛挑战':'自由实训'}</small></td><td><span class="status-chip ${r.status==='SUCCEEDED'?'':'failed'}">${statusNames[r.status]}</span></td><td>${r.duration}s<small>${r.distance} m / ${r.trace.length} 点</small></td><td>${r.score.total}<small>${r.review?'复核 '+r.review.score:'自动评分'}</small></td><td><span class="tag">运动学仿真</span></td><td><div class="cell-actions"><button class="text-btn" data-record="${r.id}">回放</button><button class="text-btn" data-export-record="${r.id}">导出</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('尚无符合条件的运行记录','从实训工作台完成一次任务，系统会自动记录参数、轨迹、技能事件和评分。',`<button class="btn dark" data-page="workspace">${icon('play')}进入实训台</button>`)}</section><div class="notice">记录保存在当前浏览器中，不会跨账号或跨设备同步。建议导出重要实验；重新加载页面不会清除已保存记录。语音转写仅用于任务输入，不采集录音。</div>`;$('#recordSearch').dataset.filter=filter;}
function renderIntegration(){$('#dynamicPage').innerHTML=heading('INTEGRATION / 06','接入与安全','明确每一层的能力边界，为后续实机适配提供接口基线。',`<button class="btn" data-action="adapter-contract">${icon('download')}下载接口约定</button>`)+`<div class="integration-grid"><section class="integration-card panel"><span class="icon-wrap">${icon('cube')}</span><h3>浏览器仿真引擎</h3><span class="status-chip">当前可用</span><p>三维示例场景、任务状态机、A* 导航、平面碰撞检查、位姿记录与实验评分。</p><button class="btn" data-page="workspace">进入实训台 →</button></section><section class="integration-card panel"><span class="icon-wrap">${icon('robot')}</span><h3>机器人 SDK / ROS 2</h3><span class="status-chip ready">等待适配与现场验证</span><p>尚无品牌、型号、SDK 与载荷曲线。当前平台不连接实机、不发送机器人动作指令。</p><button class="btn" data-action="adapter-details">查看接入清单</button></section><section class="integration-card panel"><span class="icon-wrap">${icon('flask')}</span><h3>物理仿真与策略训练</h3><span class="status-chip ready">后续扩展</span><p>接触动力学、液体、力控、RGB-D 与模型训练尚未接入。本页预设动作只用于流程验证。</p><button class="btn" data-page="validation">进入算法验证 →</button></section></div><div class="section-head"><div><h2>从仿真走向实机的接入门槛</h2><p>由机器人厂商、学校和集成方共同完成现场核验。</p></div><span class="tag">PRD §9 / §13</span></div><div class="panel table-wrap"><table><thead><tr><th>核验项</th><th>需要的输入</th><th>当前状态</th></tr></thead><tbody>${[['本体与动作能力','型号、关节自由度、末端工具、载荷曲线、可达空间'],['安全与受控执行','独立硬件急停、低速模式、监护与现场复位流程'],['状态与反馈','位姿、关节、传感器心跳、时间同步与错误码'],['场地与坐标','实测平面图、设施尺寸、原点、地图坐标与标定参数'],['教学与权限','账号服务、设备预约、角色授权、操作审批与审计'],['数据与科研','设备采样接口、数据治理、数据集版本与训练服务']].map(([a,b])=>`<tr><td><b>${a}</b></td><td>${b}</td><td><span class="status-chip ready">待提供 / 待核验</span></td></tr>`).join('')}</tbody></table></div><div class="two-columns" style="margin-top:22px"><section class="panel form-panel"><h2>软件仿真安全流程</h2><p>可以在实训工作台复现这些状态变化。</p><div class="steps-inline"><span>就绪 READY</span><span>运行 RUNNING</span><span>暂停 PAUSED</span><span>完成 / 停止</span></div><div class="notice coral">软件急停 → ABORTED → 归档 → 安全复位 → 新任务。软件按钮不替代实体硬件急停。</div><p>常温模拟杯、示意负载与预设关节动作均不构成实际温度、载重或运动控制承诺。</p></section><section class="panel form-panel"><h2>数据与使用环境</h2><p>本原型采用静态前端与浏览器本地存储，适合需求评审、课堂流程试用和初步算法实验。</p><div class="notice">存储状态：${storeOK?'当前浏览器本地存储可用':'当前浏览器存储不可用，请导出记录'}<br>体验身份：流程展示，不提供服务器权限隔离<br>三维资源：随站点提供，无外部模型下载依赖</div><button class="btn" data-action="export-all">${icon('download')}备份实验记录</button><button class="btn" data-action="help" style="margin-left:8px">使用指南</button><div style="margin-top:12px">${localPackageLink}</div></section></div>`;}

function recordModal(id){const r=db.records.find(r=>r.id===id);if(!r)return;openModal('运行证据与轨迹回放',`${SCENARIOS[r.scene].name} · ${date(r.createdAt)} · ${r.id}`,`<div class="record-summary"><span class="score-big">${r.score.total}<small> / 100</small></span><div><h3>${statusNames[r.status]} · ${esc(r.student)}</h3><p>完成度 ${r.score.completion} + 安全检查 ${r.score.safety} + 效率 ${r.score.efficiency}</p><p>时长 ${r.duration}s · 里程 ${r.distance}m · 种子 ${r.config.seed}</p></div></div><div id="replayMap">${trajectorySVG(r.trace,null,r.trace[0])}</div><div class="replay-controls"><button class="btn" data-play-record="${r.id}" id="replayPlay">${icon('play')}播放</button><input id="replaySlider" data-id="${r.id}" type="range" min="0" max="${Math.max(0,r.trace.length-1)}" value="0" step="1" aria-label="回放采样位置"><span class="small mono" id="replayTime">00:00</span></div><div class="small muted" id="replayStep">${r.trace.length?SKILLS[r.trace[0].step]?.name||'开始':'无轨迹采样'}</div><div class="timeline">${r.events.map(e=>`<div class="timeline-event"><time>${seconds(e.t)}</time>${esc(e.message)}</div>`).join('')}</div>${r.review?`<div class="notice">人工复核：${r.review.score} 分<br>理由：${esc(r.review.reason)}<br>复核于 ${date(r.review.createdAt)}；自动评分未覆盖。</div>`:''}<p class="page-note">数据来源：运动学仿真。场景尺寸、机器人外形与动作均为示例，物理夹持力、接触动力学和传感器值不包含在此记录中。</p><div class="modal-actions"><button class="btn" data-export-csv="${r.id}">${icon('download')}轨迹 CSV</button><button class="btn" data-export-record="${r.id}">记录 JSON</button><button class="btn" data-export-html="${r.id}">实验简报</button><button class="btn primary" data-replay-3d="${r.id}">${icon('cube')}三维复盘</button></div>`);}
function updateReplaySlider(r,index){const p=r.trace[index];if(!p)return;$('#replayMap').innerHTML=trajectorySVG(r.trace,null,p);$('#replayTime').textContent=seconds(p.t);$('#replayStep').textContent=`${SKILLS[p.step]?.name||'任务结束'} · X ${p.x.toFixed(3)} / Z ${p.z.toFixed(3)} m${p.carried?' · 携物中':p.placed?' · 已放置':''}`;}
function stopReplay(){replay=null;$('#threeReplayBar')?.remove();}
function beginReplay(r){if(guardRunning())return;closeModal();activeContest=null;sceneKey=r.scene;target=r.config.target;seed=r.config.seed;count=r.config.count;speed=r.config.speed;algorithm=r.config.algorithm;skills=[...r.skills];rebuild();const lengths=[0];for(let i=1;i<r.trace.length;i++)lengths.push(lengths.at(-1)+Math.hypot(r.trace[i].x-r.trace[i-1].x,r.trace[i].z-r.trace[i-1].z));replay={record:r,time:0,playing:true,lengths};navigate('workspace');scene?.drawPath(r.trace);const bar=document.createElement('div');bar.id='threeReplayBar';bar.className='replay-controls';bar.style.cssText='margin:0;padding:12px 18px;background:#eef1e5;border-top:1px solid #dce5ce';bar.innerHTML=`<button class="btn" data-action="toggle-3d-replay" id="replay3dButton">${icon('pause')}暂停回放</button><input type="range" id="threeReplaySlider" min="0" max="${r.duration}" step=".05" value="0" aria-label="三维回放时间"><span class="small mono" id="replay3dTime">00:00</span><button class="text-btn" data-action="stop-3d-replay">退出</button>`;$('.telemetry').before(bar);}
function settingsModal(){if(guardRunning())return;if(activeContest){toast('竞赛参数已冻结。可退出竞赛后配置自由实训。');return;}openModal('场景与仿真参数','参数仅用于运动学实验，不作为实体设备指标。',`<div class="form-grid"><label>随机种子<input type="number" id="settingSeed" value="${seed}" min="0" max="999999"></label><label>可变障碍数量<select id="settingCount">${[0,1,2,3,4].map(n=>`<option ${n===count?'selected':''}>${n}</option>`).join('')}</select></label><label>规划方法<select id="settingAlgorithm"><option value="astar" ${algorithm==='astar'?'selected':''}>A* 网格规划</option><option value="direct" ${algorithm==='direct'?'selected':''}>直线路径基线</option></select></label><label>当前场景<input value="${SCENARIOS[sceneKey].name}" disabled></label></div><div class="notice">场地为 10 × 7 m 示例区域；导航网格 0.25 m，机器人平面安全半径 0.28 m。实际建设须按场地测量与厂商参数替换。</div><div class="modal-actions"><button class="btn" data-action="import-task">${icon('upload')}导入任务 JSON</button><button class="btn primary" data-action="save-settings">应用参数</button></div>`);}
function planModal(){if(guardRunning())return;if(activeContest){toast('竞赛技能链已冻结。');return;}planDraft=[...skills];drawPlanModal();}
function drawPlanModal(){const error=validatePlan(planDraft,sceneKey);openModal('任务编排','调整技能顺序，检查依赖关系，或增加回位技能。',`<div>${planDraft.map((k,i)=>`<div class="plan-row"><span class="mono">${String(i+1).padStart(2,'0')}</span><strong>${SKILLS[k].name}</strong><button data-move-step="${i}" data-dir="-1" ${i===0?'disabled':''} aria-label="上移${SKILLS[k].name}">上移</button><button data-move-step="${i}" data-dir="1" ${i===planDraft.length-1?'disabled':''} aria-label="下移${SKILLS[k].name}">下移</button>${k==='home'?`<button data-remove-step="${i}">删除</button>`:''}</div>`).join('')}</div>${error?`<div class="plan-invalid">${esc(error)}</div>`:'<div class="notice">✓ 前置条件与技能顺序校验通过。</div>'}<div class="modal-actions"><button class="btn" data-action="restore-plan">恢复模板</button><button class="btn" data-action="add-home" ${planDraft.includes('home')?'disabled':''}>添加返回起始位</button><button class="btn primary" data-action="apply-plan" ${error?'disabled':''}>保存任务链</button></div>`);}
function sceneGraph(){const s=SCENARIOS[sceneKey],t=s.targets[target];openModal('空间语义关系','显式对象 ID 与空间关系参与目标校验与任务规划。',`<div class="semantic-graph"><div class="semantic-row"><strong>${sceneKey==='coffee'?'常温模拟杯':'训练箱'}<br><small>${sceneKey==='coffee'?'coffee_cup':'parcel_01'}</small></strong><span>位于 →</span><strong>${sceneKey==='coffee'?'咖啡操作台':'配送车货台'}</strong></div><div class="semantic-row"><strong>机器人 robot_01</strong><span>递送 →</span><strong>${t.name}</strong></div><div class="semantic-row"><strong>${t.name}</strong><span>导航停靠点 →</span><strong>X ${t.x} / Z ${t.z} m</strong></div><div class="semantic-row"><strong>目标放置点</strong><span>空间位置 →</span><strong>X ${t.place.x} / Y ${t.place.y} / Z ${t.place.z} m</strong></div></div><div class="notice">静态语义对象由本原型定义，尚未来自真实视觉检测或点云重建。三维坐标采用 Y 向上，导航使用 XZ 平面。</div><div class="modal-actions"><button class="btn" data-action="export-task">导出任务与场景对象</button></div>`);}
function assignmentModal(){if(!canConfigure()){toast('请切换教师体验身份。');return;}openModal('发布教学任务','保存至当前浏览器，供教学流程演示。',`<div class="form-grid"><label class="wide">任务名称<input id="assignmentTitle" maxlength="80" placeholder="例如：第 1 次咖啡服务实训"></label><label>实验单元<select id="assignmentLab">${LABS.map(l=>`<option value="${l.id}">${l.name}</option>`).join('')}</select></label><label>提交日期<input type="date" id="assignmentDue"></label><label class="wide">作业要求<textarea id="assignmentNote" rows="3" placeholder="说明需要提交的实验记录、分析与结论"></textarea></label></div><div class="modal-actions"><button class="btn primary" data-action="save-assignment">发布教学任务</button></div>`);}
function reportModal(){if(!db.records.length){toast('请先运行一次实验，获取报告所需的证据记录。');return;}openModal('提交实验报告','将观察与结论关联到实际产生的任务记录。',`<div class="form-grid"><label>实验单元<select id="reportLab">${LABS.map(l=>`<option value="${l.id}" ${l.id===activeLab?'selected':''}>${l.name}</option>`).join('')}</select></label><label>证据记录<select id="reportRun">${db.records.map(r=>`<option value="${r.id}">${date(r.createdAt)} · ${SCENARIOS[r.scene].name} · ${statusNames[r.status]}</option>`).join('')}</select></label><label class="wide">实验观察、结论与改进建议<textarea id="reportText" class="report-input" placeholder="例如：比较了两次不同目标桌位的运行，路径长度分别为……；发现……；下一步需要验证……"></textarea></label></div><div class="notice">报告以「${esc(db.name)}」提交，正文应包含观察、数据依据和改进建议，至少 20 字。</div><div class="modal-actions"><button class="btn primary" data-action="save-report">提交并关联证据</button></div>`);}
function freezeContest(){if(!canConfigure())return;const name=$('#contestName').value.trim(),sc=$('#contestScene').value,t=$('#contestTarget').value,sd=Number($('#contestSeed').value),ct=Number($('#contestCount').value);const rules={completion:Number($('#weightCompletion').value),safety:Number($('#weightSafety').value),efficiency:Number($('#weightEfficiency').value),timeLimit:Number($('#contestTime').value)};if(!name||name.length>80){toast('请输入 1–80 字的赛题名称。');return;}if(!Number.isInteger(sd)||sd<0||sd>999999){toast('随机种子须为 0–999999 的整数。');return;}if(['completion','safety','efficiency'].some(k=>!Number.isFinite(rules[k])||rules[k]<0||rules[k]>100)||Math.abs(rules.completion+rules.safety+rules.efficiency-100)>.0001){toast('三项权重须在 0–100 之间，合计为 100。');return;}if(!Number.isFinite(rules.timeLimit)||rules.timeLimit<20||rules.timeLimit>600){toast('时限须为 20–600 秒。');return;}const env=environment(sc,sd,ct);if(!planPath(env.start,env.pickup,env.obstacles)||!planPath(env.pickup,env.targets[t],env.obstacles)){toast('当前种子的任务路径不可达，请调整种子或障碍物数量后冻结。');return;}db.contest={id:crypto.randomUUID(),name,scene:sc,target:t,seed:sd,count:ct,rules,createdAt:new Date().toISOString()};save();renderCompetition();toast('赛题已冻结，参赛记录将保存规则快照。');}
function challenge(){if(!db.contest||guardRunning())return;const name=$('#studentName')?.value.trim();if(name){db.name=name.slice(0,30);save();}stopReplay();activeContest=structuredClone(db.contest);activeLab=8;sceneKey=activeContest.scene;target=activeContest.target;seed=activeContest.seed;count=activeContest.count;speed=.65;algorithm='astar';skills=defaultSkills(sceneKey);rebuild();navigate('workspace');toast(`已加载「${activeContest.name}」，点击开始仿真进行计分。`);}
function reviewModal(id){if(!canConfigure())return;const r=db.records.find(r=>r.id===id);openModal('裁判复核','原始自动评分保留，人工复核单独记录。',`<div class="notice">选手 ${esc(r.student)} · 自动评分 ${r.score.total} · ${statusNames[r.status]}</div><div class="form-grid"><label>复核分数 0–100<input id="reviewScore" type="number" min="0" max="100" step=".1" value="${r.review?.score??r.score.total}"></label><label class="wide">复核理由<textarea id="reviewReason" rows="4">${esc(r.review?.reason||'')}</textarea></label></div><div class="modal-actions"><button class="btn primary" data-save-review="${r.id}">保存复核</button></div>`);}
function help(){openModal('从第一个任务开始','共境 · 具身智能训练场 V0.1 / 依据 2026-10-21 PRD V1.0',`<div class="help-grid"><div class="help-item"><h3>01 / 学生实训</h3><p>在实训台选择咖啡或物流场景，指定桌位或柜格。点击开始仿真，观察技能、路径和事件；结束后进入数据与回放查看证据。</p></div><div class="help-item"><h3>02 / 课程实验</h3><p>选择八个实验之一，按步骤操作。任务记录保存后，在课程页提交实验报告，将结论与具体运行关联。</p></div><div class="help-item"><h3>03 / 任务竞赛</h3><p>顶部切换为教师或裁判，配置并冻结赛题；填写参赛显示名，开始挑战。自动成绩进入当前赛题榜单，可复核与导出。</p></div><div class="help-item"><h3>04 / 技术验证</h3><p>批量比较 A* 与直线路径规划。若已有同任务实测轨迹，可导入计算时间对齐后的 XZ 位置 RMSE。</p></div></div><h3>当前能力</h3><p>两类三维示例场景、规则指令解析、可校验技能编排、运动学移动与预设操作动画、二维静态碰撞检查、轨迹采样、任务回放、本地课程与报告、自定义竞赛规则和确定性路径实验。</p><h3>待接入能力</h3><p>真实机器人 SDK / ROS 2、独立硬件急停、RGB-D 与力觉、接触动力学、流体、真实本地 ASR、LLM / VLM、策略训练、服务器账号与多人数据同步。</p><p>角色切换是流程体验。场景和机器人使用程序化示意模型；尺寸、速度与评分是原型设定，不能据此认定实机性能或学校场地条件。</p><h3>语音输入</h3><p>优先使用文本指令。点击麦克风后才请求浏览器语音权限；语音服务是否可用、是否联网上传由浏览器决定，不属于本地部署 ASR。</p><h3>数据与保存</h3><p>最近 50 次运行、课程任务与报告保存在当前浏览器。JSON 保留任务和轨迹，CSV 用于分析，实验简报可通过浏览器打印为 PDF。重要实验请及时导出。</p>${localPackageLink}<h3>实施参考</h3><p>需求来源：用户提供《具身智能机器人虚实融合训练场 PRD V1.0》，2026 年 10 月 21 日，§3–§10。三维实现采用 Three.js 项目 0.180.0；参照 <a href="https://threejs.org/docs/pages/OrbitControls.html" target="_blank" rel="noopener">Three.js 官方 OrbitControls 文档</a>（2026 年 10 月查阅）。</p>`);}
function telemetryFormat(){openModal('实测轨迹数据约定','UTF-8 JSON 数组，或一行一个对象的 JSONL。',`<pre>[\n  {"t": 0.00, "x": -3.75, "z": 2.25},\n  {"t": 0.20, "x": -3.70, "z": 2.24},\n  {"t": 0.40, "x": -3.65, "z": 2.20}\n]</pre><p>t：任务开始后的秒数，非负且严格递增。x、z：统一场地坐标中的米值。2–100000 个点，文件大小不超过 10 MB。</p><p>以上仅为格式示例，不是实测记录。导入前请核对同一任务、同一坐标原点、单位与时间基准。平台对仿真轨迹做线性插值，并在重叠区间计算 RMSE。</p>`);}
function adapterDetails(){openModal('实机接入基线','当前提供协议草案，不包含可执行设备控制。',`<ol><li>提供机器人品牌型号、SDK 版本、受控技能与状态读取文档。</li><li>核验可达空间、末端夹具、负载曲线与允许速度。</li><li>统一对象 ID、米制坐标、Y 轴向上与时间戳约定。</li><li>在本地边缘网关中实现白名单技能、状态反馈与错误码。</li><li>独立硬件急停优先于软件控制，失联进入厂商定义的安全状态。</li><li>先做空载单技能，再做常温杯具和轻量箱体的受控任务。</li><li>完成账号权限、设备预约、人工审批与审计后，才开放正式实机入口。</li></ol><div class="notice coral">机器人额定载荷、SDK 能力和现场尺寸尚未提供。[!!! 事实断层：资料不足，无法确认]</div><div class="modal-actions"><button class="btn" data-action="adapter-contract">下载接口约定 JSON</button></div>`);}
function taskExport(){download(`fieldlab-task-${SCENARIOS[sceneKey].code}-${seed}.json`,{schema:'fieldlab.task.v1',version:VERSION,mode:'kinematic-simulation',config:config(),objects:environment(sceneKey,seed,count),coordinateSystem:{unit:'meter',up:'Y',navigation:'XZ'},notice:'Prototype parameters; not physical robot control.'});}
function exportHTML(r){const text=`<!DOCTYPE html><html lang="zh-CN"><head><meta charset="utf-8"><title>共境实验记录 ${esc(r.id)}</title><style>body{font-family:Arial,'Microsoft YaHei',sans-serif;max-width:900px;margin:45px auto;padding:20px;color:#2e4739;line-height:1.8}h1{font-size:27px}table{border-collapse:collapse;width:100%;font-size:12px}th,td{text-align:left;padding:9px;border-bottom:1px solid #ddd}small,p{color:#72816b}.chart-svg{width:100%;max-height:350px;background:#f3f5eb}.tag{padding:5px;background:#eee}button{padding:10px 20px}@media print{button{display:none}}</style></head><body><h1>具身智能实训实验记录</h1><p>记录 ${esc(r.id)}<br>${esc(r.createdAt)} · ${esc(r.student)}</p><p>场景：${SCENARIOS[r.scene].name} / 目标：${SCENARIOS[r.scene].targets[r.config.target].name}<br>状态：${statusNames[r.status]} / 种子：${r.config.seed} / 时长：${r.duration}s / 里程：${r.distance}m<br>自动分：${r.score.total} / 完成度 ${r.score.completion} / 安全检查 ${r.score.safety} / 效率 ${r.score.efficiency}</p>${trajectorySVG(r.trace)}<h2>执行事件</h2><table><tr><th>相对时间</th><th>事件</th><th>说明</th></tr>${r.events.map(e=>`<tr><td>${e.t}s</td><td>${esc(e.type)}</td><td>${esc(e.message)}</td></tr>`).join('')}</table><h2>能力与证据范围</h2><p>本记录来自浏览器运动学仿真。布局、模型、动作与参数为原型设定。成绩不代表实体机器人载荷、抓取稳定性、接触动力学或现场安全性能。</p><p>依据：用户提供的 2026 年 10 月 21 日 PRD V1.0 与本次实际生成的仿真日志。软件版本 ${VERSION}。</p><button onclick="window.print()">打印 / 保存 PDF</button></body></html>`;download(`fieldlab-report-${r.id.slice(0,8)}.html`,text,'text/html');}
async function perform(action){switch(action){
 case 'run':startRun();break;
 case 'estop':estop();break;
 case 'reset':if(['RUNNING','PAUSED'].includes(sim.status)){sim.abort();finish();}stopReplay();rebuild();toast('已复位，可以开始新任务。');break;
 case 'close':closeModal();break;
 case 'help':help();break;
 case 'menu':$('#sidebar').classList.toggle('open');break;
 case 'parse':parse();break;
 case 'settings':settingsModal();break;
 case 'edit-plan':planModal();break;
 case 'scene-graph':sceneGraph();break;
 case 'records':navigate('records');break;
 case 'export-task':taskExport();break;
 case 'import-task':$('#taskFile').click();break;
 case 'save-settings':{const sd=Number($('#settingSeed').value);if(!Number.isInteger(sd)||sd<0||sd>999999){toast('种子须为 0–999999 的整数。');break;}seed=sd;count=Number($('#settingCount').value);algorithm=$('#settingAlgorithm').value;closeModal();stopReplay();rebuild();toast('参数已应用，可复现当前场景。');break;}
 case 'restore-plan':planDraft=defaultSkills(sceneKey);drawPlanModal();break;
 case 'add-home':if(!planDraft.includes('home'))planDraft.push('home');drawPlanModal();break;
 case 'apply-plan':{const err=validatePlan(planDraft,sceneKey);if(err){toast(err);break;}skills=[...planDraft];closeModal();stopReplay();rebuild();toast('任务链已保存。');break;}
 case 'examples':{const list=sceneKey==='coffee'?['把咖啡送到 02 号桌','把咖啡送到沙发交付点','给张老师送咖啡','把咖啡送到 01 号桌']:['把训练箱放到 B-02 柜格','把箱子送到 B-03','把箱子送到 B-01'];const i=(list.indexOf($('#commandInput').value)+1)%list.length;$('#commandInput').value=list[i];$('#commandInput').focus();break;}
 case 'microphone':{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('此浏览器不支持语音识别，请使用文本输入。');break;}openModal('启用浏览器语音输入','语音能力由浏览器提供，当前未接入本地 ASR。',`<p>继续后浏览器将请求麦克风权限。识别服务可用性、联网行为及音频处理由浏览器决定。识别结果仅填入指令框，仍需你点击生成任务与开始仿真。</p><div class="modal-actions"><button class="btn" data-action="close">使用文本输入</button><button class="btn primary" data-action="start-mic">启用语音输入</button></div>`);break;}
 case 'start-mic':{closeModal();const SR=window.SpeechRecognition||window.webkitSpeechRecognition;const rec=new SR();rec.lang='zh-CN';rec.interimResults=false;rec.continuous=false;rec.onresult=e=>{$('#commandInput').value=e.results[0][0].transcript;toast('已填入语音转写，请检查后生成任务。');};rec.onerror=e=>toast('语音识别未完成：'+e.error+'，可继续使用文本输入。');try{rec.start();toast('正在聆听，请说出任务指令。');}catch{toast('麦克风暂不可用，请使用文本输入。');}break;}
 case 'fullscreen':{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#viewport').requestFullscreen();}catch{toast('浏览器暂不支持全屏，可以使用三维缩放与俯视视角。');}break;}
 case 'assignment':assignmentModal();break;
 case 'save-assignment':{if(!canConfigure())break;const title=$('#assignmentTitle').value.trim();if(!title){toast('请填写教学任务名称。');break;}db.assignments.unshift({id:crypto.randomUUID(),title:title.slice(0,80),labId:Number($('#assignmentLab').value),due:$('#assignmentDue').value,note:$('#assignmentNote').value.trim().slice(0,2000),createdAt:new Date().toISOString()});save();closeModal();renderCourses();toast('教学任务已保存。');break;}
 case 'submit-report':reportModal();break;
 case 'save-report':{const body=$('#reportText').value.trim();if(body.length<20||body.length>20000){toast('报告正文需为 20–20000 字。');break;}db.reports.unshift({id:crypto.randomUUID(),labId:Number($('#reportLab').value),runId:$('#reportRun').value,student:db.name,body,createdAt:new Date().toISOString()});save();closeModal();renderCourses();toast('实验报告已提交并关联证据。');break;}
 case 'freeze-contest':freezeContest();break;
 case 'new-contest':{if(!canConfigure()||guardRunning())break;db.contest=null;activeContest=null;save();renderCompetition();toast('可以配置新赛题，历史参赛记录仍保留在数据中心。');break;}
 case 'challenge':challenge();break;
 case 'save-name':{const name=$('#studentName').value.trim();if(!name){toast('请填写参赛显示名。');break;}db.name=name.slice(0,30);save();toast('显示名已保存。');break;}
 case 'export-leaderboard':{const rs=db.records.filter(r=>r.contestId===db.contest?.id).sort((a,b)=>(b.review?.score??b.score.total)-(a.review?.score??a.score.total)||a.duration-b.duration);if(!rs.length){toast('当前赛题暂无成绩。');break;}download('fieldlab-leaderboard.csv',csv(rs.map((r,i)=>({排名:i+1,姓名:r.student,任务:r.contestName,状态:r.status,完成技能:r.completed,耗时秒:r.duration,自动分:r.score.total,复核分:r.review?.score,最终分:r.review?.score??r.score.total,复核理由:r.review?.reason,记录ID:r.id,数据来源:'运动学仿真'}))),'text/csv');break;}
 case 'run-batch':{const cfg={scene:$('#batchScene').value,target:$('#batchTarget').value,seed:Number($('#batchSeed').value),count:Number($('#batchCount').value),episodes:Number($('#batchEpisodes').value)};if(!Number.isInteger(cfg.seed)||cfg.seed<0||cfg.seed>999999){toast('种子须为 0–999999 的整数。');break;}$('#batchButton').disabled=true;$('#batchButton').innerHTML='正在计算…';await new Promise(r=>setTimeout(r,30));batchConfig=cfg;try{batchResults=runBatch(cfg,cfg.episodes);renderValidation();toast(`已完成 ${cfg.episodes*2} 次路径验证。`);}catch(e){toast('实验未完成：'+e.message);renderValidation();}break;}
 case 'export-batch':if(!batchResults){toast('请先运行一次对照实验。');break;}download('fieldlab-planner-comparison.csv',csv(batchResults.map(r=>({...r,scene:batchConfig.scene,target:batchConfig.target,obstacles:batchConfig.count,version:VERSION,source:'kinematic-path-planning'}))),'text/csv');break;
 case 'telemetry-format':telemetryFormat();break;
 case 'import-telemetry':if(!$('#compareBaseline').value){toast('请先完成一次仿真作为基线。');break;}if(!$('#coordinateConfirmed').checked){toast('请先核对并勾选任务、坐标与时间基准。');break;}$('#telemetryFile').click();break;
 case 'export-comparison':if(comparison)download('fieldlab-trajectory-comparison.json',{source:'user-provided-unverified-telemetry',baselineId:comparison.baseline.id,filename:comparison.filename,rmse:comparison.rmse,max:comparison.max,overlap:comparison.overlap,samples:comparison.samples,realTrace});break;
 case 'export-all':download('fieldlab-evidence-backup.json',{schema:'fieldlab.backup.v1',exportedAt:new Date().toISOString(),...db});break;
 case 'adapter-details':adapterDetails();break;
 case 'adapter-contract':download('fieldlab-adapter-contract.json',{schema:'fieldlab.robot-adapter.draft.v1',status:'not-implemented',units:{position:'meter',time:'seconds',angle:'radian',upAxis:'Y'},taskFields:['task_id','task_version','scenario_id','robot_id','intent','target_object_id','target_location_id','skill_sequence','constraints'],stateFields:['timestamp','robot_id','pose','joint_states','current_skill','task_status','safety_state','heartbeat','error_code'],permittedSkillTypes:['navigate','grasp','place','press_button','controlled_stop'],safetyRequirements:['independent_physical_emergency_stop','local_watchdog_and_vendor_safe_state','teacher_authorization','speed_and_payload_limits_from_manufacturer','validated_coordinate_calibration'],note:'Proposed integration contract only. No live robot commands or network adapter implemented.'});break;
 case 'toggle-3d-replay':if(replay){replay.playing=!replay.playing;$('#replay3dButton').innerHTML=icon(replay.playing?'pause':'play')+(replay.playing?'暂停回放':'继续回放');}break;
 case 'stop-3d-replay':stopReplay();rebuild();break;
}}

document.addEventListener('click',async e=>{const el=e.target.closest('button,a');if(!el)return;if(el.dataset.page){navigate(el.dataset.page);return;}if(el.dataset.scene){changeScene(el.dataset.scene);return;}if(el.dataset.view){scene?.setView(el.dataset.view);return;}if(el.dataset.layer){el.classList.toggle('active');scene?.setLayers({[el.dataset.layer]:el.classList.contains('active')});return;}if(el.dataset.action){try{await perform(el.dataset.action);}catch(err){console.error(err);toast('操作未完成：'+err.message);}return;}
 if(el.dataset.lab){labModal(el.dataset.lab);return;}
 if(el.dataset.loadLab){if(guardRunning())return;activeLab=Number(el.dataset.loadLab);activeContest=null;const l=LABS.find(l=>l.id===activeLab);closeModal();changeScene(l.scene);if(activeLab===7)navigate('validation');else if(activeLab===8)navigate('competition');else navigate('workspace');toast(`已加载实验 ${String(l.id).padStart(2,'0')}。`);return;}
 if(el.dataset.courseFilter){courseFilter=el.dataset.courseFilter;renderCourses();return;}
 if(el.dataset.recordFilter){renderRecords(el.dataset.recordFilter);return;}
 if(el.dataset.record){recordModal(el.dataset.record);return;}
 if(el.dataset.exportRecord){const r=db.records.find(r=>r.id===el.dataset.exportRecord);download(`fieldlab-run-${r.id.slice(0,8)}.json`,r);return;}
 if(el.dataset.exportCsv){const r=db.records.find(r=>r.id===el.dataset.exportCsv);download(`fieldlab-trace-${r.id.slice(0,8)}.csv`,csv(r.trace),'text/csv');return;}
 if(el.dataset.exportHtml){exportHTML(db.records.find(r=>r.id===el.dataset.exportHtml));return;}
 if(el.dataset.playRecord){const r=db.records.find(r=>r.id===el.dataset.playRecord);if(replayTimer){clearInterval(replayTimer);replayTimer=null;el.innerHTML=icon('play')+'播放';return;}el.innerHTML=icon('pause')+'暂停';if(Number($('#replaySlider').value)>=r.trace.length-1)$('#replaySlider').value=0;replayTimer=setInterval(()=>{const i=Number($('#replaySlider')?.value||0)+1;if(!$('#replaySlider')||i>=r.trace.length){clearInterval(replayTimer);replayTimer=null;if($('#replayPlay'))$('#replayPlay').innerHTML=icon('play')+'播放';return;}$('#replaySlider').value=i;updateReplaySlider(r,i);},150);return;}
 if(el.dataset['replay-3d']){const r=db.records.find(r=>r.id===el.dataset['replay-3d']);if(r.trace.length<2){toast('该记录轨迹不足，无法回放。');return;}beginReplay(r);return;}
 if(el.dataset.review){reviewModal(el.dataset.review);return;}
 if(el.dataset.saveReview){if(!canConfigure())return;const score=Number($('#reviewScore').value),reason=$('#reviewReason').value.trim();if(!Number.isFinite(score)||score<0||score>100||reason.length<5){toast('请输入 0–100 的分数和至少 5 字的复核理由。');return;}const r=db.records.find(r=>r.id===el.dataset.saveReview);r.review={score:Math.round(score*10)/10,reason:reason.slice(0,3000),createdAt:new Date().toISOString(),role:db.role};save();closeModal();renderCompetition();toast('复核结果已保存，原始评分保留。');return;}
 if(el.dataset.report){const r=db.reports.find(r=>r.id===el.dataset.report);openModal('实验报告',`${esc(r.student)} · ${date(r.createdAt)} · 实验 ${r.labId}`,`<p style="white-space:pre-wrap">${esc(r.body)}</p><div class="notice">关联运行 ID：${esc(r.runId)}</div><div class="modal-actions"><button class="btn" data-record="${r.runId}">查看证据</button></div>`);return;}
 if(el.dataset.moveStep!==undefined){const i=Number(el.dataset.moveStep),j=i+Number(el.dataset.dir);[planDraft[i],planDraft[j]]=[planDraft[j],planDraft[i]];drawPlanModal();return;}
 if(el.dataset.removeStep!==undefined){planDraft.splice(Number(el.dataset.removeStep),1);drawPlanModal();}
});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='roleSelect'){db.role=el.value;save();$('#avatar').textContent={student:'学',teacher:'师',judge:'裁',admin:'管'}[db.role];if(page!=='workspace')navigate(page);toast('已切换体验身份；此原型不提供正式账号权限隔离。');}if(el.id==='targetSelect'){if(guardRunning())return;target=el.value;stopReplay();rebuild();renderIntent();}if(el.id==='speedSelect'){speed=Number(el.value);rebuild();}if(el.id==='contestScene'||el.id==='batchScene'){const targetSelect=el.id==='contestScene'?$('#contestTarget'):$('#batchTarget');targetSelect.innerHTML=Object.entries(SCENARIOS[el.value].targets).map(([k,t])=>`<option value="${k}">${t.name}</option>`).join('');}});
document.addEventListener('input',e=>{if(e.target.id==='replaySlider'){const r=db.records.find(r=>r.id===e.target.dataset.id);updateReplaySlider(r,Number(e.target.value));}if(e.target.id==='threeReplaySlider'&&replay)replay.time=Number(e.target.value);if(e.target.id==='recordSearch'){const value=e.target.value,filter=e.target.dataset.filter,pos=e.target.selectionStart;renderRecords(filter,value);$('#recordSearch').focus();$('#recordSearch').setSelectionRange(pos,pos);}});
$('#commandInput').addEventListener('keydown',e=>{if(e.key==='Enter')parse();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal();}});
$('#modal').addEventListener('close',()=>{clearInterval(replayTimer);replayTimer=null;});
$('#telemetryFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('文件需小于 10 MB');const text=await file.text();let data;if(file.name.endsWith('.jsonl'))data=text.split(/\r?\n/).filter(l=>l.trim()).map(l=>JSON.parse(l));else data=JSON.parse(text);const trace=validateTelemetry(data),baseline=db.records.find(r=>r.id===$('#compareBaseline').value);const result=trajectoryError(baseline.trace,trace);realTrace=trace;comparison={...result,filename:file.name,baseline};$('#comparisonOutput').innerHTML=comparisonHTML();toast('已完成时间对齐与位置误差计算。');}catch(err){toast('导入失败：'+err.message);}e.target.value='';});
$('#taskFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('任务文件需小于 2 MB');const data=JSON.parse(await file.text()),c=data.config;if(data.schema!=='fieldlab.task.v1'||!c||!SCENARIOS[c.scene]||!SCENARIOS[c.scene].targets[c.target])throw Error('任务格式或场景目标无效');if(!Array.isArray(c.skills)||c.skills.some(k=>!SKILLS[k]))throw Error('技能列表无效');const err=validatePlan(c.skills,c.scene);if(err)throw Error(err);if(!Number.isInteger(c.seed)||c.seed<0||c.seed>999999||!Number.isInteger(c.count)||c.count<0||c.count>4||![.45,.65,.9].includes(c.speed)||!['astar','direct'].includes(c.algorithm))throw Error('参数超出原型支持范围');if(guardRunning())return;activeContest=null;stopReplay();({scene:sceneKey,target,seed,count,speed,algorithm,skills}=c);closeModal();rebuild();navigate('workspace');renderIntent();toast('任务已导入，可使用相同种子复现。');}catch(err){toast('导入失败：'+err.message);}e.target.value='';});
$('#nav').innerHTML=NAV.map(([id,i,label,num])=>`<a href="#${id}" class="nav-item" data-page="${id}">${icon(i)}<span>${label}</span><span class="nav-number">${num}</span></a>`).join('');
$('#roleSelect').value=db.role;$('#avatar').textContent={student:'学',teacher:'师',judge:'裁',admin:'管'}[db.role]||'学';icons();
try{const {LabScene}=await import('./scene.js');scene=new LabScene($('#viewport'),o=>{$('#objectInspector').innerHTML=`<span class="object-icon">${icon(o.id==='robot_01'?'robot':'cube')}</span><div><strong>${esc(o.name)}</strong><p>${esc(o.type)}<br>X ${Number(o.x).toFixed(2)} / Z ${Number(o.z).toFixed(2)} m</p><code>${esc(o.id)}</code></div>`;});}catch(err){console.error(err);const fallback=document.createElement('div');fallback.className='loading-note';fallback.textContent='三维资源加载失败。任务计算、教学与记录仍可使用，请刷新页面重试。';$('#viewport').appendChild(fallback);}
rebuild();navigate(location.hash.slice(1)||'workspace');let last=performance.now(),lastUI=0;
function frame(now){const dt=Math.min((now-last)/1000,.1);last=now;if(replay){if(replay.playing)replay.time=Math.min(replay.record.duration,replay.time+dt);const trace=replay.record.trace;let p=trace[0],pi=0;for(let i=0;i<trace.length;i++){if(trace[i].t>replay.time)break;p=trace[i];pi=i;}replay.pose=p;replay.distance=replay.lengths[pi];replay.completed=replay.record.events.filter(e=>e.type==='COMPLETE'&&e.t<=replay.time).length;replay.stepIndex=replay.record.skills.indexOf(p.step);const k=replay.record.skills.indexOf(p.step);scene?.update({...p,pos:{x:p.x,z:p.z},status:'REPLAY',skills:replay.record.skills,index:k},dt);if($('#threeReplaySlider'))$('#threeReplaySlider').value=replay.time;if($('#replay3dTime'))$('#replay3dTime').textContent=seconds(replay.time);$('#liveTime').textContent=seconds(replay.time);$('#livePos').textContent=`${p.x.toFixed(2)} / ${p.z.toFixed(2)}`;if(replay.time>=replay.record.duration){replay.playing=false;if($('#replay3dButton'))$('#replay3dButton').innerHTML=icon('play')+'回放完成';}}else{sim.update(dt);if(activeContest&&sim.status==='RUNNING'&&sim.elapsed>=activeContest.rules.timeLimit){sim.status='FAILED';sim.event('TIMEOUT','已达到赛题时限，任务停止');sim.sample(true);}scene?.update(sim,dt);finish();}if(now-lastUI>100){updateUI();lastUI=now;}requestAnimationFrame(frame);}requestAnimationFrame(frame);
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));window.addEventListener('pagehide',()=>{if(['RUNNING','PAUSED'].includes(sim.status)){sim.abort();finish();}});
